                        <div className="absolute inset-0 rounded-[2.5rem] border-2 border-transparent group-hover:border-primary-300/50 transition-all duration-1000 pointer-events-none"></div>

                        <div className="absolute inset-0 bg-gradient-to-br from-primary-500/10 via-secondary-500/10 to-primary-500/10 rounded-[2.5rem] opacity-0 group-hover:opacity-100 transition-all duration-1000 blur-xl pointer-events-none"></div>

                      </div>

                    </div>

                  </div>

                </div>

              </div>

            </div>

          </div>



          {/* Navigation Dots */}

          <div className="flex justify-center space-x-2 mt-8">

            {[0, 1, 2].map((index) => (

              <button

                key={index}

                onClick={() => setFeatureSlide(index)}

                className={`w-3 h-3 rounded-full transition-all duration-300 ${

                  featureSlide === index 

                    ? 'bg-gradient-to-r from-primary-500 to-secondary-500 w-8' 

                    : 'bg-gray-300 dark:bg-gray-600 hover:bg-gray-400 dark:hover:bg-gray-500'

                }`}

              />

            ))}

          </div>

        </div>

      </section>

      {/* Modern Subscription Plans Section */}
      <section className="mb-16">
        {/* Section Header */}
        <div className="text-center mb-12">
          <div className="inline-block relative group">
            <h2 className={`text-4xl md:text-5xl font-bold mb-4 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
              <span className="bg-gradient-to-r from-primary-600 via-secondary-600 to-primary-600 bg-clip-text text-transparent">
                Subscription Plans
              </span>
            </h2>
            <div className="absolute -bottom-2 left-0 w-full h-1 bg-gradient-to-r from-primary-500 to-secondary-500 rounded-full transform scale-x-0 group-hover:scale-x-100 transition-transform duration-500"></div>
          </div>
          <p className={`text-lg ${isDarkMode ? 'text-gray-300' : 'text-gray-600'} mt-4 max-w-2xl mx-auto`}>
            Choose the perfect milk delivery plan for your family's needs
          </p>
        </div>

        {/* Subscription Plans Container */}
        <div className="relative bg-gradient-to-br from-gray-50 via-white to-gray-100 dark:from-gray-900 dark:via-gray-800 dark:to-gray-900 rounded-3xl p-8 shadow-2xl">
          
          {/* Animated Background Elements */}
          <div className="absolute inset-0 overflow-hidden rounded-3xl">
            <div className="absolute top-10 left-10 w-32 h-32 bg-gradient-to-br from-primary-500/10 to-secondary-500/10 rounded-full blur-3xl animate-pulse"></div>
            <div className="absolute bottom-10 right-10 w-40 h-40 bg-gradient-to-br from-secondary-500/10 to-primary-500/10 rounded-full blur-3xl animate-pulse animation-delay-2"></div>
            <div className="absolute top-1/2 left-1/3 w-24 h-24 bg-gradient-to-br from-blue-500/8 to-purple-500/8 rounded-full blur-2xl animate-pulse animation-delay-4"></div>
          </div>

          {/* Plans Grid */}
          <div className="relative grid grid-cols-1 md:grid-cols-3 gap-8">
            
            {/* Daily Plan */}
            <div className="group relative">
              <div className={`relative overflow-hidden rounded-2xl border-2 transition-all duration-500 transform hover:scale-105 hover:-translate-y-2 ${
                isDarkMode 
                  ? 'bg-gray-800/90 border-gray-700/50 hover:border-primary-500/50' 
                  : 'bg-white/90 border-gray-200/50 hover:border-primary-500/50'
              } shadow-xl backdrop-blur-md`}>
                
                {/* Plan Header */}
                <div className="relative p-6 text-center border-b border-gray-200/20 dark:border-gray-700/20">
                  <div className="inline-flex items-center justify-center w-16 h-16 bg-gradient-to-br from-green-500 to-emerald-500 rounded-full mb-4">
                    <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                  </div>
                  <h3 className={`text-2xl font-bold mb-2 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>Daily</h3>
                  <div className="flex items-baseline justify-center">
                    <span className="text-4xl font-bold text-primary-600 dark:text-primary-400">₹29</span>
                    <span className={`text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-600'} ml-1`}>/day</span>
                  </div>
                  <p className={`text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-600'} mt-2`}>Fresh milk every morning</p>
                </div>

                {/* Plan Features */}
                <div className="p-6 space-y-3">
                  <div className="flex items-center">
                    <svg className="w-5 h-5 text-green-500 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                    <span className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>500ml Fresh Milk Daily</span>
                  </div>
                  <div className="flex items-center">
                    <svg className="w-5 h-5 text-green-500 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                    <span className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>6:00 AM - 7:00 AM Delivery</span>
                  </div>
                  <div className="flex items-center">
                    <svg className="w-5 h-5 text-green-500 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                    <span className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>Pause Anytime</span>
                  </div>
                  <div className="flex items-center">
                    <svg className="w-5 h-5 text-green-500 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                    <span className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>Free Delivery</span>
                  </div>
                </div>

                {/* CTA Button */}
                <div className="p-6 pt-0">
                  <button 
                    onClick={() => handleSubscribe('daily')}
                    className="w-full py-3 bg-gradient-to-r from-green-500 to-emerald-500 text-white font-semibold rounded-xl hover:from-green-600 hover:to-emerald-600 transform transition-all duration-300 hover:scale-105 shadow-lg"
                  >
                    Start Daily Plan
                  </button>
                </div>

                {/* Popular Badge */}
                <div className="absolute top-4 right-4 bg-gradient-to-r from-green-500 to-emerald-500 text-white text-xs font-bold px-3 py-1 rounded-full">
                  POPULAR
                </div>
              </div>
            </div>

            {/* Weekly Plan */}
            <div className="group relative">
              <div className={`relative overflow-hidden rounded-2xl border-2 transition-all duration-500 transform hover:scale-105 hover:-translate-y-2 ${
                isDarkMode 
                  ? 'bg-gray-800/90 border-gray-700/50 hover:border-primary-500/50' 
                  : 'bg-white/90 border-gray-200/50 hover:border-primary-500/50'
              } shadow-xl backdrop-blur-md`}>
                
                {/* Plan Header */}
                <div className="relative p-6 text-center border-b border-gray-200/20 dark:border-gray-700/20">
                  <div className="inline-flex items-center justify-center w-16 h-16 bg-gradient-to-br from-blue-500 to-cyan-500 rounded-full mb-4">
                    <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
                    </svg>
                  </div>
                  <h3 className={`text-2xl font-bold mb-2 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>Weekly</h3>
                  <div className="flex items-baseline justify-center">
                    <span className="text-4xl font-bold text-primary-600 dark:text-primary-400">₹189</span>
                    <span className={`text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-600'} ml-1`}>/week</span>
                  </div>
                  <p className={`text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-600'} mt-2`}>Perfect for small families</p>
                </div>

                {/* Plan Features */}
                <div className="p-6 space-y-3">
                  <div className="flex items-center">
                    <svg className="w-5 h-5 text-blue-500 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                    <span className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>3.5L Milk Per Week</span>
                  </div>
                  <div className="flex items-center">
                    <svg className="w-5 h-5 text-blue-500 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                    <span className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>Flexible Delivery Days</span>
                  </div>
                  <div className="flex items-center">
                    <svg className="w-5 h-5 text-blue-500 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                    <span className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>10% Discount</span>
                  </div>
                  <div className="flex items-center">
                    <svg className="w-5 h-5 text-blue-500 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                    <span className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>Free Delivery</span>
                  </div>
                </div>

                {/* CTA Button */}
                <div className="p-6 pt-0">
                  <button 
                    onClick={() => handleSubscribe('weekly')}
                    className="w-full py-3 bg-gradient-to-r from-blue-500 to-cyan-500 text-white font-semibold rounded-xl hover:from-blue-600 hover:to-cyan-600 transform transition-all duration-300 hover:scale-105 shadow-lg"
                  >
                    Start Weekly Plan
                  </button>
                </div>
              </div>
            </div>

            {/* Monthly Plan */}
            <div className="group relative">
              <div className={`relative overflow-hidden rounded-2xl border-2 transition-all duration-500 transform hover:scale-105 hover:-translate-y-2 ${
                isDarkMode 
                  ? 'bg-gray-800/90 border-gray-700/50 hover:border-primary-500/50' 
                  : 'bg-white/90 border-gray-200/50 hover:border-primary-500/50'
              } shadow-xl backdrop-blur-md`}>
                
                {/* Plan Header */}
                <div className="relative p-6 text-center border-b border-gray-200/20 dark:border-gray-700/20">
                  <div className="inline-flex items-center justify-center w-16 h-16 bg-gradient-to-br from-purple-500 to-pink-500 rounded-full mb-4">
                    <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                  </div>
                  <h3 className={`text-2xl font-bold mb-2 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>Monthly</h3>
                  <div className="flex items-baseline justify-center">
                    <span className="text-4xl font-bold text-primary-600 dark:text-primary-400">₹799</span>
                    <span className={`text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-600'} ml-1`}>/month</span>
                  </div>
                  <p className={`text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-600'} mt-2`}>Best value for families</p>
                </div>

                {/* Plan Features */}
                <div className="p-6 space-y-3">
                  <div className="flex items-center">
                    <svg className="w-5 h-5 text-purple-500 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                    <span className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>15L Milk Per Month</span>
                  </div>
                  <div className="flex items-center">
                    <svg className="w-5 h-5 text-purple-500 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                    <span className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>Custom Schedule</span>
                  </div>
                  <div className="flex items-center">
                    <svg className="w-5 h-5 text-purple-500 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                    <span className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>20% Discount</span>
                  </div>
                  <div className="flex items-center">
                    <svg className="w-5 h-5 text-purple-500 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                    <span className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>Free Delivery + Priority</span>
                  </div>
                </div>

                {/* CTA Button */}
                <div className="p-6 pt-0">
                  <button 
                    onClick={() => handleSubscribe('monthly')}
                    className="w-full py-3 bg-gradient-to-r from-purple-500 to-pink-500 text-white font-semibold rounded-xl hover:from-purple-600 hover:to-pink-600 transform transition-all duration-300 hover:scale-105 shadow-lg"
                  >
                    Start Monthly Plan
                  </button>
                </div>

                {/* Best Value Badge */}
                <div className="absolute top-4 right-4 bg-gradient-to-r from-purple-500 to-pink-500 text-white text-xs font-bold px-3 py-1 rounded-full">
                  BEST VALUE
                </div>
              </div>
            </div>

          </div>

          {/* Additional Benefits */}
          <div className="mt-12 text-center">
            <div className={`inline-flex items-center px-6 py-3 rounded-full ${
              isDarkMode ? 'bg-gray-800/60 border border-gray-700/50' : 'bg-white/60 border border-gray-200/50'
            } backdrop-blur-md shadow-lg`}>
              <svg className="w-5 h-5 text-primary-500 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
              <span className={`text-sm font-medium ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
                All plans include: Pause/Resume anytime • No cancellation fees • 24/7 support
              </span>
            </div>
          </div>

        </div>
      </section>

      {/* Toast Container */}

      {toasts.map(toast => (

        <Toast

          key={toast.id}

          message={toast.message}

          type={toast.type}

          duration={toast.duration}

          onClose={() => removeToast(toast.id)}

        />

      ))}

    </div>

  );

};



export default Home;
